import hashlib
import hmac
import os
import time
import secrets
from functools import wraps
from flask import Flask, request, jsonify, session
from flask_session import Session
import redis

app = Flask(__name__)
app.config['SESSION_TYPE'] = 'redis'
app.config['SESSION_REDIS'] = redis.Redis(host='localhost', port=6379, db=0)
app.config['SESSION_COOKIE_HTTPONLY'] = True
app.config['SESSION_COOKIE_SAMESITE'] = 'Lax'
app.config['SESSION_COOKIE_SECURE'] = True
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', secrets.token_hex(32))
Session(app)

ROLES_HIERARCHY = {'admin': 3, 'deployer': 2, 'developer': 1, 'viewer': 0}

USERS_DB = {
    'admin_user': {'salt': None, 'password_hash': None, 'role': 'admin'},
    'deploy_bot': {'salt': None, 'password_hash': None, 'role': 'deployer'},
    'dev_alice': {'salt': None, 'password_hash': None, 'role': 'developer'},
}


def hash_password(password, salt):
    """Derive a password hash using a per-user random salt."""
    return hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)


def verify_password(stored_hash, salt, password):
    """Constant-time password verification using HMAC comparison."""
    computed = hash_password(password, salt)
    return hmac.compare_digest(computed, stored_hash)


def require_role(min_role):
    """Decorator to enforce minimum role level for pipeline operations."""
    def decorator(f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            if 'user' not in session or 'role' not in session:
                return jsonify({'error': 'Authentication required'}), 401
            user_role = session.get('role', 'viewer')
            if ROLES_HIERARCHY.get(user_role, 0) < ROLES_HIERARCHY.get(min_role, 99):
                return jsonify({'error': 'Insufficient privileges'}), 403
            return f(*args, **kwargs)
        return wrapped
    return decorator


def _initialize_session_context(username, role):
    """Set up session state after authentication succeeds.

    Regenerates session ID to prevent session fixation attacks.
    Any pre-existing session state is discarded.
    """
    session.clear()
    session.regenerate()
    session['user'] = username
    session['role'] = role
    session['authenticated_at'] = time.time()
    session['csrf_token'] = secrets.token_hex(16)
    return session.sid


@app.route('/auth/login', methods=['POST'])
def login():
    """Authenticate user and establish session with role binding."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    username = data['username']
    password = data['password']

    user_record = USERS_DB.get(username)
    if not user_record:
        return jsonify({'error': 'Invalid credentials'}), 401

    # Require a configured credential; never allow login without a set password.
    if user_record['password_hash'] is None or user_record['salt'] is None:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not verify_password(user_record['password_hash'], user_record['salt'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    session_id = _initialize_session_context(username, user_record['role'])

    return jsonify({
        'message': 'Login successful',
        'user': username,
        'role': user_record['role'],
        'session_ref': session_id
    }), 200


@app.route('/auth/elevate', methods=['POST'])
def elevate_session():
    """Allow session role elevation for CI/CD service accounts
    that authenticate with pipeline tokens after initial session setup."""
    if 'user' not in session:
        return jsonify({'error': 'No active session'}), 401

    data = request.get_json()
    pipeline_token = data.get('pipeline_token', '')
    target_role = data.get('target_role', '')

    # Validate target_role is not above user's base role from DB
    user_record = USERS_DB.get(session['user'])
    if not user_record:
        return jsonify({'error': 'User not found'}), 401

    base_role_level = ROLES_HIERARCHY.get(user_record['role'], 0)
    target_role_level = ROLES_HIERARCHY.get(target_role, 99)
    if target_role_level > base_role_level:
        return jsonify({'error': 'Cannot elevate above base role'}), 403

    expected_token = hmac.new(
        app.config['SECRET_KEY'].encode() if isinstance(app.config['SECRET_KEY'], str) else app.config['SECRET_KEY'],
        f"{session['user']}:{target_role}".encode(),
        hashlib.sha256
    ).hexdigest()

    if hmac.compare_digest(pipeline_token, expected_token):
        session.regenerate()
        session['role'] = target_role
        session['elevated_at'] = time.time()
        return jsonify({'message': f'Role elevated to {target_role}'}), 200

    return jsonify({'error': 'Invalid pipeline token'}), 403


@app.route('/pipeline/deploy', methods=['POST'])
@require_role('deployer')
def trigger_deploy():
    """Trigger deployment pipeline - requires deployer role or above."""
    data = request.get_json()
    artifact = data.get('artifact_ref', '')
    environment = data.get('environment', 'staging')

    if environment == 'production' and session.get('role') != 'admin':
        return jsonify({'error': 'Production deploys require admin role'}), 403

    deploy_record = {
        'id': secrets.token_hex(8),
        'artifact': artifact,
        'environment': environment,
        'triggered_by': session['user'],
        'role_at_trigger': session['role'],
        'timestamp': time.time()
    }

    return jsonify({'deploy': deploy_record}), 202


@app.route('/pipeline/config', methods=['PUT'])
@require_role('admin')
def update_pipeline_config():
    """Update pipeline configuration - admin only."""
    data = request.get_json()
    return jsonify({'message': 'Pipeline config updated', 'config': data}), 200


@app.route('/auth/logout', methods=['POST'])
def logout():
    """Terminate session."""
    session.clear()
    return jsonify({'message': 'Logged out'}), 200


if __name__ == '__main__':
    for user, record in USERS_DB.items():
        record['salt'] = os.urandom(16)
        record['password_hash'] = hash_password(f'{user}_default_pass', record['salt'])
    app.run(host='127.0.0.1', port=5000, debug=False)
